UPDATE policy_contact_address
SET active_flag='N', review_status='S', updated_by=#{operatorId}, updated_at=CURRENT_TIMESTAMP,
    reviewed_by=#{operatorId}, reviewed_at=CURRENT_TIMESTAMP, record_version=record_version+1
WHERE policy_no=#{value.policyNo} AND policy_seq=#{value.policySeq}
  AND address_type_code=#{value.addressTypeCode} AND active_flag='Y' AND record_version=#{expectedVersion}

UPDATE policy_coverage
SET active_flag='N', review_status='S', updated_by=#{operatorId}, updated_at=CURRENT_TIMESTAMP,
    reviewed_by=#{operatorId}, reviewed_at=CURRENT_TIMESTAMP, record_version=record_version+1
WHERE policy_no=#{value.policyNo} AND policy_seq=#{value.policySeq}
  AND coverage_item_seq=#{value.coverageItemSeq} AND active_flag='Y' AND record_version=#{expectedVersion}

UPDATE code_definition
SET code_before=#{value.codeBefore}, code_after=#{value.codeAfter}, code_description=#{value.codeDescription}, active_flag=#{value.activeFlag},
    review_status='S', updated_by=#{operatorId}, updated_at=CURRENT_TIMESTAMP,
    reviewed_by=#{operatorId}, reviewed_at=CURRENT_TIMESTAMP, record_version=record_version+1
WHERE code_group=#{before.codeGroup} AND code_field=#{before.codeField} AND code_before=#{before.codeBefore}
  AND active_flag='Y' AND record_version=#{expectedVersion}

UPDATE code_definition
SET active_flag='N', review_status='S', updated_by=#{operatorId}, updated_at=CURRENT_TIMESTAMP,
    reviewed_by=#{operatorId}, reviewed_at=CURRENT_TIMESTAMP, record_version=record_version+1
WHERE code_group=#{value.codeGroup} AND code_field=#{value.codeField} AND code_before=#{value.codeBefore}
  AND active_flag='Y' AND record_version=#{expectedVersion}

UPDATE policy_change_case_reservation
SET consumed_at = CURRENT_TIMESTAMP
WHERE change_case_no = #{changeCaseNo}
  AND reserved_by = #{reservedBy}
  AND consumed_at IS NULL
  AND expires_at > CURRENT_TIMESTAMP

