mapper.update:
UPDATE policy_change_acceptance
SET acceptance_status = #{acceptance.acceptanceStatus},
    updated_by = #{acceptance.reviewedBy},
    updated_at = CURRENT_TIMESTAMP,
    reviewed_by = COALESCE(#{acceptance.reviewedBy}, reviewed_by),
    reviewed_at = COALESCE(#{acceptance.reviewedAt}, reviewed_at)
WHERE policy_no = #{acceptance.policyNo}
  AND policy_seq = #{acceptance.policySeq}
  AND change_case_no = #{acceptance.changeCaseNo}
  AND acceptance_status = #{expectedStatus}

UPDATE policy_contact_address
SET postal_code = #{postalCode},
    address_text = #{addressText}
WHERE policy_no = #{policyNo}
  AND policy_seq = #{policySeq}
  AND address_type_code = #{addressTypeCode}

UPDATE policy_coverage
SET insured_amount = CAST(#{insuredAmount} AS DECIMAL(18, 2))
WHERE policy_no = #{policyNo}
  AND policy_seq = #{policySeq}
  AND coverage_item_seq = #{coverageItemSeq}

UPDATE policy_coverage
SET premium_amount = CAST(#{premiumAmount} AS DECIMAL(18, 4))
WHERE policy_no = #{policyNo}
  AND policy_seq = #{policySeq}
  AND coverage_item_seq = #{coverageItemSeq}

UPDATE policy_contract
SET premium_amount = (
    SELECT COALESCE(SUM(ride.premium_amount), 0)
    FROM policy_coverage ride
    WHERE ride.policy_no = #{policyNo}
      AND ride.policy_seq = #{policySeq}
)
WHERE policy_no = #{policyNo}
  AND policy_seq = #{policySeq}
